const envConfig = $input.first().json;
const epochStart = Date.now();

return [{
  json: {
    ...envConfig,
    epochStart,
    timestampISO: new Date(epochStart).toISOString(),
    telemetry_markers: [{ marker: 'pipeline_init', timestamp: epochStart, duration: 0 }]
  }
}];

const pipelineData = $input.first().json;
const currentEpoch = Date.now();
const telemetry_markers = [...pipelineData.telemetry_markers, { marker: 'stage_a_resolved', timestamp: currentEpoch, duration: currentEpoch - pipelineData.epochStart }];
return [{ json: { ...pipelineData, telemetry_markers } }];

const context = $input.first().json;
const epochEnd = Date.now();
const totalLatencyMs = epochEnd - context.epochStart;

const telemetry_markers = [...context.telemetry_markers, { marker: 'pipeline_terminated', timestamp: epochEnd, duration: totalLatencyMs }];

const analysisReport = {
  jobName: $workflow.name,
  jobId: $workflow.id,
  runId: $execution.id,
  epochStart: context.epochStart,
  timestampISO: context.timestampISO,
  epochEnd,
  closedAtISO: new Date(epochEnd).toISOString(),
  totalLatencyMs,
  runtimeSec: Number((totalLatencyMs / 1000).toFixed(3)),
  latency_sla_ms: context.latency_sla_ms,
  perf_history_path: context.perf_history_path,
  incident_log_path: context.incident_log_path,
  isSlaViolated: totalLatencyMs > context.latency_sla_ms,
  telemetry_markers
};

return [{ json: analysisReport }];

// No require('fs') needed!
try {
  // Pulls the data read by your upstream "Read File" node
  const metricsPayload = $('Name_Of_Your_Read_File_Node').item.json; 

  if (!metricsPayload) {
    return 'Historical profiling empty. Unable to formulate base benchmark.';
  }
  return JSON.stringify(metricsPayload);
} catch (err) {
  return 'Failure accessing telemetry store: ' + err.message;
}

const diagnosticReport = $input.first().json;
const workflowMetadata = $('Compile Performance Metrics').first().json;

const incidentReportPayload = {
  incidentReportMarkdown: diagnosticReport.output,
  recordedAt: new Date().toISOString(),
  runId: workflowMetadata.runId,
  totalLatencyMs: workflowMetadata.totalLatencyMs,
  latency_sla_ms: workflowMetadata.latency_sla_ms
};

const formattedLogEntry = JSON.stringify(incidentReportPayload) + "\n";
const byteBuffer = await this.helpers.prepareBinaryData(Buffer.from(formattedLogEntry, 'utf-8'), 'incident-alerts.json', 'application/json');

return [{ json: incidentReportPayload, binary: { data: byteBuffer } }];
